<section class="section about" id="about"><div class="container about-grid"><div class="about-visual" data-reveal><img src="<?=e(image_path($c['about_image']))?>" loading="lazy" width="1536" height="1024" alt="<?= site_copy('about_alt') ?>"><div class="about-label"><span><?= copy_lines('about_caption') ?></span></div></div><div class="about-copy" data-reveal><p class="eyebrow"><?= site_copy('about_label') ?></p><h2><?=e($c['about_title'])?></h2><p><?=e($c['about_text'])?></p><h3 class="about-subtitle"><?=e($c['about_subtitle'])?></h3><?php foreach($c['about_points'] as $point): ?><div class="about-item"><h3><?=e($point['title'])?></h3><?php foreach($point['paragraphs'] as $paragraph): ?><p><?=e($paragraph)?></p><?php endforeach; ?></div><?php endforeach; ?><?php if (in_array('faq', $visibleSections, true)): ?><a class="text-link" href="#faq"><?=site_copy('about_more')?></a><?php endif; ?></div></div></section>
